+import { auto, mock } from 'angular';
+
+import { IPipeline, IStage } from 'core/domain';
+import {
+  ARTIFACT_REFERENCE_SERVICE_PROVIDER,
+  ArtifactReferenceServiceProvider
+} from './artifactReferenceServiceProvider';
+
+describe('ArtifactReferenceServiceProvider', () => {
+  let provider: ArtifactReferenceServiceProvider;
+  let service: ArtifactReferenceServiceProvider;
+
+  beforeEach(() => {
+    mock.module(
+      ARTIFACT_REFERENCE_SERVICE_PROVIDER,
+      (artifactReferenceServiceProvider: ArtifactReferenceServiceProvider) => {
+        provider = artifactReferenceServiceProvider;
+      }
+    );
+
+    mock.inject(($injector: auto.IInjectorService) => {
+      service = provider.$get($injector);
+    });
+  });
+
+  describe('registration', () => {
+    it('registers single reference path for a stage type', () => {
+      provider.registerReferencePath('deployManifest', 'manifestArtifactId');
+      expect(service.getRegisteredReferencePaths('deployManifest')).toEqual(['manifestArtifactId']);
+    });
+
+    it('registers multiple reference paths for a stage type', () => {
+      provider.registerReferencePaths('deployManifest', ['manifestArtifactId', 'requiredArtifactIds']);
+      expect(service.getRegisteredReferencePaths('deployManifest')).toEqual([
+        'manifestArtifactId',
+        'requiredArtifactIds'
+      ]);
+    });
+
+    it('accumulates multiple registrations for the same stage type', () => {
+      provider.registerReferencePath('customStage', 'fieldA');
+      provider.registerReferencePath('customStage', 'fieldB');
+      provider.registerReferencePaths('customStage', ['fieldC', 'fieldD']);
+      expect(service.getRegisteredReferencePaths('customStage')).toEqual([
+        'fieldA',
+        'fieldB',
+        'fieldC',
+        'fieldD'
+      ]);
+    });
+
+    it('handles register with string and array', () => {
+      provider.register('stageA', 'pathA');
+      provider.register('stageB', ['pathB1', 'pathB2']);
+      expect(service.getRegisteredReferencePaths('stageA')).toEqual(['pathA']);
+      expect(service.getRegisteredReferencePaths('stageB')).toEqual(['pathB1', 'pathB2']);
+    });
+
+    it('returns empty array for unregistered stage type', () => {
+      expect(service.getRegisteredReferencePaths('unknownStage')).toEqual([]);
+    });
+
+    it('includes wildcard paths for all stage types', () => {
+      provider.registerReferencePath('*', 'commonArtifactId');
+      provider.registerReferencePath('deployManifest', 'manifestArtifactId');
+
+      expect(service.getRegisteredReferencePaths('deployManifest')).toEqual([
+        'manifestArtifactId',
+        'commonArtifactId'
+      ]);
+      expect(service.getRegisteredReferencePaths('otherStage')).toEqual(['commonArtifactId']);
+    });
+
+    it('checks hasReferencePaths correctly', () => {
+      expect(service.hasReferencePaths('stageA')).toBe(false);
+      provider.registerReferencePath('stageA', 'fieldA');
+      expect(service.hasReferencePaths('stageA')).toBe(true);
+    });
+  });
+
+  describe('artifact removal sweep', () => {
+    beforeEach(() => {
+      provider.registerReferencePaths('deployManifest', [
+        'manifestArtifactId',
+        'requiredArtifactIds'
+      ]);
+      provider.registerReferencePaths('customStage', [
+        'nested.expectedArtifactId',
+        'artifacts[0]',
+        'containers[0].artifactId',
+        'containers.imageDescription.artifactId'
+      ]);
+    });
+
+    it('removes top-level matching property and leaves other properties untouched', () => {
+      const stage: IStage = {
+        type: 'deployManifest',
+        name: 'Deploy',
+        manifestArtifactId: 'art-123',
+        cloudProvider: 'kubernetes'
+      } as any;
+
+      service.removeArtifactFromStage('art-123', stage);
+
+      expect((stage as any).manifestArtifactId).toBeUndefined();
+      expect(stage.name).toBe('Deploy');
+      expect(stage.cloudProvider).toBe('kubernetes');
+    });
+
+    it('leaves top-level property untouched if artifact ID does not match', () => {
+      const stage: IStage = {
+        type: 'deployManifest',
+        name: 'Deploy',
+        manifestArtifactId: 'art-456'
+      } as any;
+
+      service.removeArtifactFromStage('art-123', stage);
+
+      expect((stage as any).manifestArtifactId).toBe('art-456');
+    });
+
+    it('removes deeply nested matching property', () => {
+      const stage: IStage = {
+        type: 'customStage',
+        name: 'Custom',
+        nested: {
+          expectedArtifactId: 'art-123',
+          otherConfig: 'keepMe'
+        }
+      } as any;
+
+      service.removeArtifactFromStage('art-123', stage);
+
+      expect((stage as any).nested.expectedArtifactId).toBeUndefined();
+      expect((stage as any).nested.otherConfig).toBe('keepMe');
+    });
+
+    it('leaves stage unchanged if nested path cannot be fully resolved', () => {
+      const stage: IStage = {
+        type: 'customStage',
+        name: 'Custom'
+      } as any;
+
+      service.removeArtifactFromStage('art-123', stage);
+
+      expect((stage as any).nested).toBeUndefined();
+      expect(stage.name).toBe('Custom');
+    });
+
+    it('removes all matching occurrences from an array field and preserves non-matching entries', () => {
+      const stage: IStage = {
+        type: 'deployManifest',
+        name: 'Deploy',
+        requiredArtifactIds: ['art-123', 'art-456', 'art-123', 'art-789']
+      } as any;
+
+      service.removeArtifactFromStage('art-123', stage);
+
+      expect((stage as any).requiredArtifactIds).toEqual(['art-456', 'art-789']);
+    });
+
+    it('removes array element referenced by index if matching', () => {
+      const stage: IStage = {
+        type: 'customStage',
+        name: 'Custom',
+        artifacts: ['art-123', 'art-456']
+      } as any;
+
+      service.removeArtifactFromStage('art-123', stage);
+
+      expect((stage as any).artifacts).toEqual(['art-456']);
+    });
+
+    it('leaves array untouched when element at referenced index does not match', () => {
+      const stage: IStage = {
+        type: 'customStage',
+        name: 'Custom',
+        artifacts: ['art-456', 'art-123']
+      } as any;
+
+      // path artifacts[0] is art-456, not art-123
+      service.removeArtifactFromStage('art-123', stage);
+
+      expect((stage as any).artifacts).toEqual(['art-456', 'art-123']);
+    });
+
+    it('removes nested field within array element referenced by index', () => {
+      const stage: IStage = {
+        type: 'customStage',
+        name: 'Custom',
+        containers: [
+          { artifactId: 'art-123', image: 'nginx' },
+          { artifactId: 'art-123', image: 'redis' }
+        ]
+      } as any;
+
+      service.removeArtifactFromStage('art-123', stage);
+
+      expect((stage as any).containers[0].artifactId).toBeUndefined();
+      expect((stage as any).containers[0].image).toBe('nginx');
+      expect((stage as any).containers[1].artifactId).toBe('art-123');
+    });
+
+    it('removes nested fields across all array elements when array path without index is used', () => {
+      const stage: IStage = {
+        type: 'customStage',
+        name: 'Custom',
+        containers: [
+          { imageDescription: { artifactId: 'art-123', tag: 'latest' } },
+          { imageDescription: { artifactId: 'art-456', tag: 'v1' } },
+          { imageDescription: { artifactId: 'art-123', tag: 'v2' } }
+        ]
+      } as any;
+
+      service.removeArtifactFromStage('art-123', stage);
+
+      expect((stage as any).containers[0].imageDescription.artifactId).toBeUndefined();
+      expect((stage as any).containers[0].imageDescription.tag).toBe('latest');
+      expect((stage as any).containers[1].imageDescription.artifactId).toBe('art-456');
+      expect((stage as any).containers[2].imageDescription.artifactId).toBeUndefined();
+      expect((stage as any).containers[2].imageDescription.tag).toBe('v2');
+    });
+
+    it('sweeps across all stages in a pipeline', () => {
+      const pipeline: IPipeline = {
+        stages: [
+          {
+            type: 'deployManifest',
+            name: 'Stage 1',
+            manifestArtifactId: 'art-123',
+            requiredArtifactIds: ['art-123', 'art-999']
+          },
+          {
+            type: 'deployManifest',
+            name: 'Stage 2',
+            manifestArtifactId: 'art-999',
+            requiredArtifactIds: ['art-888']
+          },
+          {
+            type: 'customStage',
+            name: 'Stage 3',
+            nested: { expectedArtifactId: 'art-123' }
+          },
+          {
+            type: 'manualJudgment',
+            name: 'Stage 4',
+            instructions: 'Approve this stage'
+          }
+        ]
+      } as any;
+
+      service.removeArtifactFromPipeline(pipeline, 'art-123');
+
+      const s1: any = pipeline.stages[0];
+      const s2: any = pipeline.stages[1];
+      const s3: any = pipeline.stages[2];
+      const s4: any = pipeline.stages[3];
+
+      expect(s1.manifestArtifactId).toBeUndefined();
+      expect(s1.requiredArtifactIds).toEqual(['art-999']);
+
+      expect(s2.manifestArtifactId).toBe('art-999');
+      expect(s2.requiredArtifactIds).toEqual(['art-888']);
+
+      expect(s3.nested.expectedArtifactId).toBeUndefined();
+
+      expect(s4.instructions).toBe('Approve this stage');
+    });
+
+    it('accepts expectedArtifact object or artifactId string interchangeably', () => {
+      const pipeline: IPipeline = {
+        stages: [
+          {
+            type: 'deployManifest',
+            manifestArtifactId: 'art-123'
+          }
+        ]
+      } as any;
+
+      service.removeArtifactFromPipeline(pipeline, { id: 'art-123' } as any);
+      expect((pipeline.stages[0] as any).manifestArtifactId).toBeUndefined();
+    });
+
+    it('handles argument order flexibility', () => {
+      const pipeline: IPipeline = {
+        stages: [
+          {
+            type: 'deployManifest',
+            manifestArtifactId: 'art-123'
+          }
+        ]
+      } as any;
+
+      service.removeArtifactFromPipeline('art-123', pipeline);
+      expect((pipeline.stages[0] as any).manifestArtifactId).toBeUndefined();
+    });
+
+    it('handles null/undefined pipeline or stages gracefully', () => {
+      expect(() => service.removeArtifactFromPipeline(null, 'art-123')).not.toThrow();
+      expect(() => service.removeArtifactFromPipeline({} as any, 'art-123')).not.toThrow();
+      expect(() => service.removeArtifactFromPipeline({ stages: null } as any, 'art-123')).not.toThrow();
+      expect(() => service.removeArtifactFromStage('art-123', null)).not.toThrow();
+      expect(() => service.removeArtifactFromStage('art-123', {} as any)).not.toThrow();
+    });
+  });
+});

